. The other three stills do not generate videos.')}</p><button className="primary" type="button" disabled={!chosen || !!busy} onClick={() => void run('render')}>{t('Gerar vídeo com esta foto', 'Generate video with this still')}{credits !== null ? ` · ${credits} ${t('créditos', 'credits')}` : ''}</button></> : null}{stage === 'rendering' ? <p role="status">{t('O vídeo está sendo preparado a partir da foto escolhida.', 'The video is being prepared from your selected still.')}</p> : null}{stage === 'delivered' && videoUrl ? <video className="ace-result" src={videoUrl} controls playsInline preload="metadata" /> : null}<div className="ace-actions"><button type="button" disabled={sessionDenied || !!busy || stage === 'stills' || stage === 'rendering'} onClick={reset}>{t('Começar outro plano', 'Start another plan')}</button></div></section> : null}
