    const t = window.setTimeout(() => {
      try { headingRef.current?.closest('section')?.scrollIntoView({ block: 'start', behavior: 'smooth' }) } catch { /* navegador antigo */ }
    }, 60)
    return () => window.clearTimeout(t)
  }, [phase])

