    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [brandTick])

  // KINEO-ANUNCIO-CONSERTOS-2026-10-12 — "Save as my brand kit" NÃO vem marcado quando já existe um kit com OUTRO nome de marca
