    note: { warn: boolean; text: string } | null
    limits: { narration_words: number; overlay_chars: number }
    voiceOn: boolean
    onStart: () => void
    onChange: (next: { narration: string; overlays: string[] }) => void
    onSave: () => void
    onCancel: () => void
