  stored.cena.keyframe = j.url; stored.cena.keyframes = [j.url!, j.url!]; stored.cena.phase = 'video'; stored.cena.jobs = []
  for (const note of f.quality_notes ?? []) addAjusteQuality(stored.cena, note)
