      else { if (await markShot(admin, row, ['pending'], { status: 'image_done', image_url: lock.url })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: why }); return } // KINEO-ADS-FIEL-1510
    } // KINEO-ADS-FIEL-1510
  } // KINEO-ADS-FIEL-1510
  if (lock && lock.mode === 'scene' && sendRefs !== refs) sendPrompt = adsV2LockedScenePromptAt({ sceneIdx: row.movement_variant, setting: adsV2SettingFromPrompt(planned?.scenePrompt), format: adsV2PlanFormat(order.plan), side: lockSideOf(order, row) }) // KINEO-ADS-FIEL-4-1510 — a cena já nasce com o CANTO reservado vazio (o MESMO lado em que o recorte será colado) e a gente na metade oposta
  if (inHand && ihLib && inHand.object && sendRefs.length > 0) { const refUrl = await inHandCropLib().then((m) => (m ? m.adsV2InHandReferenceCrop({ userId: order.user_id, cacheKey: order.id, productUrl: sendRefs[0], object: inHand.object }) : null)).catch(() => null); if (refUrl) sendRefs = [refUrl, ...sendRefs.slice(1)] } // KINEO-ADS-MAO-JUIZ-1610 — o que entra na referência entra na cena: o plano da caixa recebe o recorte SÓ da caixa (o do frasco, só o frasco); falhou = a foto inteira
  let outcome
  if (inHand && ihLib && row.reason === ihLib.ADS_V2_IN_HAND_NO_LABEL_REASON) sendPrompt = `${ihLib.adsV2InHandScenePrompt({ frame: 'no_label', settingLine: ihLib.adsV2InHandSettingFrom(planned?.scenePrompt), format: adsV2PlanFormat(order.plan), extraRefs: (planned?.referenceUrls?.length ?? 0) > 1, singleProduct: typeof planned?.scenePrompt === 'string' && planned.scenePrompt.includes(ihLib.ADS_V2_IN_HAND_SINGLE_PRODUCT), object: inHand.object })}${anchorUrl ? ` ${ADS_V2_SAME_PERSON_LINE}` : ''}` // KINEO-ADS-PRODUTO-NA-MAO-1610 — o juiz reprovou 2 vezes: o enquadramento sem o rótulo de frente · KINEO-ADS-MAO-AJUSTE-1610 — + um produto só (como no pedido gravado) · KINEO-ADS-MAO-AJUSTE-3-1610 — + o objeto único do plano
  try {
    outcome = await submitSceneImage({ prompt: sendPrompt, referenceUrls: sendRefs, ...(adsV2PlanFormat(order.plan) !== '9:16' ? { aspect: adsV2PlanFormat(order.plan) } : {}), ...(sendRefs !== refs || inHand ? { outputFormat: 'png' as const } : {}), ...(pv ? { numImages: 4 as const } : {}) }, { userId: order.user_id, orderId: order.id }) // KINEO-APRESENTADOR-V2-1710 — + as 4 opções do apresentador // KINEO-ADS-MELHORIAS-1410 — a cena criada no formato do anúncio · KINEO-ADS-FIEL-1510 — com a trava: o esboço + PNG · KINEO-ADS-MAO-JUIZ-1610 — + o produto na mão em PNG (o juiz recorta o produto gerado)
  } catch (e) {
    // buildSceneImageInput recusou (nada saiu daqui): recusa NOSSA, não refazer.
    await failShot(admin, row, ['pending'], `scene_input_invalid:${e instanceof Error ? e.message : String(e)}`, 'local_policy_gate')
    return
  }
  if (outcome.kind === 'accepted') {
    await markShot(admin, row, ['pending'], { status: 'image_submitted', image_request_id: outcome.requestId })
  } else if (outcome.kind === 'ambiguous') {
    await markShot(admin, row, ['pending'], { status: 'ambiguous', reason: 'image_submit_ambiguous', reason_class: outcome.reasonClass })
    // Resposta tardia ainda nesta lambda: grava o id (o job existe; nada é reenviado).
    void outcome.late.then(async (id) => {
      if (id) await admin.from('ads_v2_shots').update({ status: 'image_submitted', image_request_id: id, reason: null }).eq('id', row.id).eq('status', 'ambiguous').is('image_request_id', null)
    }).catch(() => {})
  } else {
    await failShot(admin, row, ['pending'], `image_submit_rejected:${outcome.status ?? 'none'}`, outcome.reasonClass)
  }
}

async function submitVideoFor(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow): Promise<void> {
  // REGRA DURA: texto e o vídeo do cliente nunca passam por IA de vídeo — nem por engano de linha (engine nulo também não sai).
  if (neverAi(row) || !row.engine) return
  const engine = row.engine
  const claimed = await markShot(admin, row, ['pending', 'image_done'], { submit_claimed_at: nowIso() }, 'submit_claimed_at')
  if (!claimed) return
  const pv = engine === 'kling_avatar' && row.kind === ADS_V2_PRESENTER_KIND ? await presenterV2Of(order) : null // KINEO-APRESENTADOR-V2-AJUSTE-1710 — o apresentador v2: a atuação dele e o motor PRO
  const tail = pv ? await presenterV2TailVoice(order, pv) : null // KINEO-APRESENTADOR-V2-AJUSTE-3-1710 — o áudio do motor com ~0,6 s de silêncio no fim (null = a voz de sempre)
  let input: Record<string, unknown>
  try {
    // KINEO-ESTILOS-PRODUTO-2026-10-09 — o efeito sai da chave gravada no plano do pedido (só o 'pixverse_effect' a usa).
    // KINEO-ATOR-ANUNCIO-2026-10-09 — o ator leva a voz do anúncio (só ele usa audioUrl; sem voz https, recusa local).
    input = buildShotInput(engine, { imageUrl: row.image_url ?? '', prompt: pv ? pv.lib.adsV2PresenterV2PerformanceOf(row.prompt) : videoPromptOf(order, row), audioUrl: tail ? tail.url : order.voice_url ?? '', effect: adsV2ShotEffect(order.plan, row.idx) }) as unknown as Record<string, unknown> // KINEO-APRESENTADOR-V2-AJUSTE-3-1710 — tail = a voz com o silêncio do fim (só o v2) · KINEO-ADS-FIEL-1510 — videoPromptOf: sem trava = row.prompt ?? '' (o de sempre) · KINEO-APRESENTADOR-V2-AJUSTE-1710 — o v2 nunca leva a atuação de 09/10 ("upbeat… visible-hand gestures")
    if (pv) input = pv.lib.adsV2PresenterV2AvatarInput(input) // KINEO-APRESENTADOR-V2-AJUSTE-1710 — negative prompt só se o motor aceitar (hoje não: o mesmo corpo)
    if (engine === 'kling_o3' && inHandTagOf(order, row.idx)) { const ih = await inHandLib(); if (ih) input = ih.adsV2InHandKlingInput({ imageUrl: row.image_url ?? '', prompt: videoPromptOf(order, row), cutStart: num(row.cut_start), cutSeconds: num(row.cut_seconds) }) as unknown as Record<string, unknown> } // KINEO-ADS-PRODUTO-NA-MAO-1610 — plano novo: 3 s · KINEO-ADS-MAO-AJUSTE-1610 — SEM quadro final (o end_image_url congelava a pessoa) · KINEO-ADS-MAO-AJUSTE-3-1610 — a duração pelo trecho (3 s; 4 s nos planos de 3,1 s)
    if (engine === 'seedance_20_fast' && adsV2PlanFormat(order.plan) === '1:1') input = { ...input, aspect_ratio: adsV2SeedanceAspect('1:1') } // KINEO-ADS-MELHORIAS-1410 — o herói do Premium QUADRADO sai em 1:1 (o schema da fal aceita; 4:5 não existe lá e o /plan recusa antes)
  } catch (e) {
    // O efeito recusado AQUI não mata o anúncio: 'invalid_payload' entra na refação automática e, na 3ª tentativa, a
    // reserva H3 anima a mesma foto com o prompt de movimento normal. Nos motores de antes, a recusa local segue terminal.
    await failShot(admin, row, ['pending', 'image_done'], `shot_input_invalid:${e instanceof Error ? e.message : String(e)}`, engine === 'pixverse_effect' ? 'invalid_payload' : 'local_policy_gate')
    return
  }
  const spec = ADS_V2_ENGINES[engine]
  // KINEO-ATOR-ANUNCIO-2026-10-09 — o ator gera a duração da VOZ (o custo real dele); os outros motores, a do catálogo.
  const genSeconds = engine === 'kling_avatar' ? Math.round(((num(order.voice_seconds) ?? spec.genSeconds) + (tail ? tail.seconds : 0)) * 1000) / 1000 : spec.genSeconds // KINEO-APRESENTADOR-V2-AJUSTE-3-1710 — + o silêncio do fim (o motor cobra o áudio inteiro)
  const slug = pv ? pv.lib.ADS_V2_PRESENTER_V2_ENGINE_SLUG : spec.slug // KINEO-APRESENTADOR-V2-AJUSTE-1710 — o v2 no Kling AI Avatar v2 PRO (1080p); a fila da fal consulta pelo app (fal-ai/kling-video): o poll de sempre lê
  const usdPerSecond = pv ? pv.lib.ADS_V2_PRESENTER_V2_USD_PER_SECOND : spec.usdPerSecond // KINEO-APRESENTADOR-V2-AJUSTE-1710
  const outcome = await submitShotOnce(slug, input, { userId: order.user_id, orderId: order.id }) // KINEO-APRESENTADOR-V2-AJUSTE-1710 — era spec.slug
  if (outcome.kind === 'accepted') {
    await markShot(admin, row, ['pending', 'image_done'], {
      status: 'submitted',
      request_id: outcome.requestId,
      submitted_at: nowIso(),
      gen_seconds: genSeconds,
      usd: Math.round(usdPerSecond * genSeconds * 10000) / 10000, // KINEO-APRESENTADOR-V2-AJUSTE-1710 — o preço do motor que saiu (o PRO no v2)
    })
  } else if (outcome.kind === 'ambiguous') {
    await markShot(admin, row, ['pending', 'image_done'], { status: 'ambiguous', reason: 'submit_ambiguous', reason_class: outcome.reasonClass, submitted_at: nowIso() })
    void outcome.late.then(async (id) => {
      if (id) await admin.from('ads_v2_shots').update({ status: 'submitted', request_id: id, reason: null }).eq('id', row.id).eq('status', 'ambiguous').is('request_id', null)
    }).catch(() => {})
  } else {
    await failShot(admin, row, ['pending', 'image_done'], `submit_rejected:${outcome.status ?? 'none'}`, outcome.reasonClass)
  }
}

/**
 * Envia o que está pronto para sair: imagens das cenas criadas (antes do vídeo) e vídeos. Concorrência moderada:
 * Kling O3 em série com pausa curta; Seedance/H3/Nano Banana em lotes de 3. Para de abrir envio novo no prazo.
 */
export async function dispatchAdsV2Shots(admin: SupabaseClient, order: AdsV2OrderRow, deadlineMs: number): Promise<number> {
  if ((order.plan as { cena?: { plan?: { marker?: string } } } | null)?.cena?.plan?.marker === 'KINEO-ADS-CENA-2110') return 0 // KINEO-ADS-CENA-2110 — nenhuma cena envia planos pelo motor legado
  // Pedido que já falhou/entregou (outra lambda venceu entre a leitura e aqui) não manda NADA à fal.
  if (order.status !== 'generating') return 0
  const rows = await loadAdsV2Shots(admin, order.id)
  if (!rows) return 0
  const latest = latestShots(rows)
  // KINEO-ATOR-ANUNCIO-2026-10-09 — a foto do ator só sai com a narração ligada; o vídeo dele, só com a voz pronta e
  // dentro do teto (adsV2PresenterVoiceReady). Os planos do anúncio não mudam.
  const images = latest.filter(needsImage).filter((r) => r.kind !== ADS_V2_PRESENTER_KIND || order.narration === true)
    .filter((r) => !adsV2LockOf(order, r) || deadlineMs - Date.now() >= ADS_V2_LOCK_DISPATCH_MIN_MS) // KINEO-ADS-FIEL-1510 — cena com trava (recorte até 45 s) só sai de quem tem fôlego: o /start (60 s) deixa para a tela/cron
  // KINEO-ADS-FIEL-2-1510 — o CLOSE do Premium com a trava ligada para a conta nunca vai ao motor (Seedance/H3 redesenharam tampa, base e
  // KINEO-ADS-FIEL-2-1510 — líquido no QA de 15/10): vira a foto real com zoom de close. Trava desligada / servidor fora = o caminho de antes.
  const closeups = latest.filter((r) => adsV2LockCloseupEligible(r) && !r.submit_claimed_at) // KINEO-ADS-FIEL-2-1510
  const closed = new Set<number>() // KINEO-ADS-FIEL-2-1510
  if (closeups.length > 0) { // KINEO-ADS-FIEL-2-1510
    const srv = await lockServer() // KINEO-ADS-FIEL-2-1510
    if (srv && (await srv.adsV2ProductLockEnabled(order.user_id).catch(() => false))) for (const r of closeups) { await closeupStill(admin, order, r); closed.add(r.idx) } // KINEO-ADS-FIEL-2-1510
  } // KINEO-ADS-FIEL-2-1510
  const videos = latest.filter(needsVideo).filter((r) => r.kind !== ADS_V2_PRESENTER_KIND || adsV2PresenterVoiceReady(order))
    .filter((r) => !closed.has(r.idx)) // KINEO-ADS-FIEL-2-1510 — o close já virou a foto real
  const kling = videos.filter((r) => r.engine === 'kling_o3')
  const others = videos.filter((r) => r.engine !== 'kling_o3')
  let sent = 0
  const batch = async (list: AdsV2ShotRow[], fn: (r: AdsV2ShotRow) => Promise<void>) => {
    for (let i = 0; i < list.length; i += ADS_V2_BATCH_SIZE) {
      if (Date.now() > deadlineMs) return
      const part = list.slice(i, i + ADS_V2_BATCH_SIZE)
      await Promise.all(part.map((r) => fn(r).catch((e) => console.warn('[ads-v2] envio falhou:', e instanceof Error ? e.message : String(e)))))
      sent += part.length
    }
  }
  await batch(images, (r) => submitImageFor(admin, order, r))
  await batch(others, (r) => submitVideoFor(admin, order, r))
  for (const r of kling) {
    if (Date.now() > deadlineMs) break
    await submitVideoFor(admin, order, r).catch((e) => console.warn('[ads-v2] envio Kling falhou:', e instanceof Error ? e.message : String(e)))
    sent += 1
    await sleep(ADS_V2_KLING_GAP_MS)
  }
  return sent
}
/** KINEO-ADS-FIEL-4-1510 — o lado do canto reservado da cena: pela ORDEM dela entre as cenas travadas do plano (1ª direita, 2ª esquerda…).
 *  A MESMA conta no pedido da imagem e na colagem — é o que faz o recorte cair no canto que a cena deixou vazio. */
function lockSideOf(order: AdsV2OrderRow, row: Pick<AdsV2ShotRow, 'idx'>): AdsV2LockSide { // KINEO-ADS-FIEL-4-1510
  const shots = Array.isArray(order.plan?.shots) ? order.plan!.shots : [] // KINEO-ADS-FIEL-4-1510
  const idxs = shots.filter((s) => adsV2LockOf(order, { idx: s.idx, kind: s.kind })?.mode === 'scene').map((s) => s.idx) // KINEO-ADS-FIEL-4-1510
  return adsV2LockSideFor(adsV2LockSceneOrdinal(idxs, row.idx)) // KINEO-ADS-FIEL-4-1510
} // KINEO-ADS-FIEL-4-1510
/** KINEO-ADS-FIEL-4-1510 — os rostos CRUS que a conferência devolveu nas OUTRAS cenas travadas do pedido (o `seen` do JSON ao lado de cada
 *  quadro): o palpite repetido entre cenas é reconhecido. Melhor esforço: fora do ar = [] (só a regra da caixa redonda vale). Nunca lança. */
async function lockSeenOfSiblings(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow): Promise<AdsV2Box[][]> { // KINEO-ADS-FIEL-4-1510
  try { // KINEO-ADS-FIEL-4-1510
    const r = await admin.from('ads_v2_shots').select('idx,attempt,image_url').eq('order_id', order.id) // KINEO-ADS-FIEL-4-1510
    const urls = ((r.data ?? []) as { idx: number; image_url: string | null }[]).filter((x) => x.idx !== row.idx).map((x) => adsV2LockSidecarUrl(x.image_url)).filter((u): u is string => !!u) // KINEO-ADS-FIEL-4-1510
    const got = await Promise.all(urls.slice(0, 8).map(async (u) => { try { const res = await fetch(u, { signal: AbortSignal.timeout(5_000), cache: 'no-store' }); return res.ok ? adsV2ParseLockSeen(await res.text()) : [] } catch { return [] } })) // KINEO-ADS-FIEL-4-1510
    return got.filter((g) => g.length > 0) // KINEO-ADS-FIEL-4-1510
  } catch { // KINEO-ADS-FIEL-4-1510
    return [] // KINEO-ADS-FIEL-4-1510
  } // KINEO-ADS-FIEL-4-1510
} // KINEO-ADS-FIEL-4-1510
/** KINEO-ADS-FIEL-6-1610 — quantas cenas do plano têm a trava no canto (o denominador do limite global da conferência). */
function lockSceneCount(order: AdsV2OrderRow): number { // KINEO-ADS-FIEL-6-1610
  const shots = Array.isArray(order.plan?.shots) ? order.plan!.shots : [] // KINEO-ADS-FIEL-6-1610
  return shots.filter((s) => adsV2LockOf(order, { idx: s.idx, kind: s.kind })?.mode === 'scene').length // KINEO-ADS-FIEL-6-1610
} // KINEO-ADS-FIEL-6-1610
/** KINEO-ADS-FIEL-6-1610 — as linhas (idx, tentativa) das OUTRAS cenas travadas do pedido; erro = nenhuma. */
async function lockSiblingRows(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow): Promise<{ idx: number; attempt: number }[]> { // KINEO-ADS-FIEL-6-1610
  try { // KINEO-ADS-FIEL-6-1610
    const shots = Array.isArray(order.plan?.shots) ? order.plan!.shots : [] // KINEO-ADS-FIEL-6-1610
    const locked = new Set(shots.filter((s) => adsV2LockOf(order, { idx: s.idx, kind: s.kind })?.mode === 'scene').map((s) => s.idx)) // KINEO-ADS-FIEL-6-1610
    const r = await admin.from('ads_v2_shots').select('idx,attempt').eq('order_id', order.id) // KINEO-ADS-FIEL-6-1610
    return ((r.data ?? []) as { idx: number; attempt: number }[]).filter((x) => x.idx !== row.idx && locked.has(x.idx)).map((x) => ({ idx: x.idx, attempt: x.attempt })) // KINEO-ADS-FIEL-6-1610
  } catch { // KINEO-ADS-FIEL-6-1610
    return [] // KINEO-ADS-FIEL-6-1610
  } // KINEO-ADS-FIEL-6-1610
} // KINEO-ADS-FIEL-6-1610
/**
 * KINEO-ADS-FIEL-4-1510 — a cena de gente com a trava: o recorte REAL vai ao CANTO reservado (lado pela ordem da cena; base no terço de baixo).
 * A conferência ('high') só decide se o canto está ocupado: confiável e com gente no canto = refaz a imagem UMA vez (scene_retry, a mesma régua
 * da Fiel 2) e, de novo, a vaga anima a FOTO REAL do produto. Conferência suspeita ou fora do ar = o canto fica. Falha do servidor = a foto real.
 */
async function finishReservedScene(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow, lock: AdsV2ProductLock, sceneUrl: string, srv: NonNullable<Awaited<ReturnType<typeof lockServer>>>): Promise<'done'> { // KINEO-ADS-FIEL-4-1510
  const side = lockSideOf(order, row) // KINEO-ADS-FIEL-4-1510
  const format = adsV2PlanFormat(order.plan) // KINEO-ADS-FIEL-4-1510
  try { // KINEO-ADS-FIEL-4-1510
    const check = await lockVision().then((v) => (v && typeof v.adsV2SceneCheck === 'function' ? v.adsV2SceneCheck(sceneUrl, format, side) : null)).catch(() => null) // KINEO-ADS-FIEL-4-1510
    const previous = await lockSeenOfSiblings(admin, order, row) // KINEO-ADS-FIEL-4-1510
    const history = typeof srv.adsV2ReadLockChecks === 'function' ? await srv.adsV2ReadLockChecks({ userId: order.user_id, orderId: order.id, rows: await lockSiblingRows(admin, order, row) }) : [] // KINEO-ADS-FIEL-6-1610 — o que a conferência disse nas OUTRAS cenas travadas (repetição e limite global)
    const out = await srv.adsV2FinishReservedScene({ userId: order.user_id, orderId: order.id, idx: row.idx, attempt: row.attempt, lock, format, sceneUrl, side, check, previous, history, totalScenes: lockSceneCount(order), tryN: adsV2LockCheckTry(row.reason) }) // KINEO-ADS-FIEL-4-1510 · KINEO-ADS-FIEL-6-1610 — + o histórico, o total de cenas travadas e a tentativa (1ª ou depois da refação)
    const checkInfo = { trusted: out.trust.trusted, why: out.trust.why, corner_person: check ? check.cornerPerson : null, corner_surface: check ? check.cornerSurface : null, round: !!check && Array.isArray(check.faces) && check.faces.some(adsV2LockBoxRound), top_edge_raw: check && typeof check.topEdgeY === 'number' ? check.topEdgeY : null, corner: out.corner ?? null, people: check && Array.isArray(check.people) ? check.people.length : null, guess: typeof out.guess === 'number' ? out.guess : null } // KINEO-ADS-FIEL-5-1510 — + check.round (caixa na grade de 0,05) e a borda do tampo crua · KINEO-ADS-FIEL-6-1610 — + por que o canto ficou/saiu e quantos corpos · KINEO-ADS-FIEL-7-1610 — + quantas caixas eram chute
    if (out.busy) { // KINEO-ADS-FIEL-4-1510
      if (adsV2LockCornerStep({ busy: true, previousReason: row.reason }) === 'retry') { // KINEO-ADS-FIEL-4-1510
        if (await markShot(admin, row, ['image_submitted'], { status: 'pending', image_request_id: null, image_submit_claimed_at: null, reason: ADS_V2_LOCK_CORNER_REASON })) await shotFallbackEvent(order, row, { to: 'scene_retry', reason: ADS_V2_LOCK_CORNER_REASON, side, problem: out.problem, check: checkInfo }) // KINEO-ADS-FIEL-4-1510
        return 'done' // KINEO-ADS-FIEL-4-1510
      } // KINEO-ADS-FIEL-4-1510
      if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: lock.url, reason: null })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: 'lock_corner_busy', side, problem: out.problem, check: checkInfo }) // KINEO-ADS-FIEL-4-1510
      return 'done' // KINEO-ADS-FIEL-4-1510
    } // KINEO-ADS-FIEL-4-1510
    if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: out.url })) { // KINEO-ADS-FIEL-4-1510
      await writeServerEvent({ name: 'ads_v2_product_locked', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, idx: row.idx, attempt: row.attempt, mode: lock.mode, rect: out.rect, shade: out.shade, placement: out.placement, faces: out.faces, check: checkInfo, from_original: !!lock.sourceUrl } }).catch(() => null) // KINEO-ADS-FIEL-4-1510 — placement.source 'reserved' + o que a conferência disse
    } // KINEO-ADS-FIEL-4-1510
    return 'done' // KINEO-ADS-FIEL-4-1510
  } catch (e) { // KINEO-ADS-FIEL-4-1510
    const why = e instanceof Error ? e.message : String(e) // KINEO-ADS-FIEL-4-1510
    if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: lock.url })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: `lock_finish:${why}`.slice(0, 160) }) // KINEO-ADS-FIEL-4-1510
    return 'done' // KINEO-ADS-FIEL-4-1510
  } // KINEO-ADS-FIEL-4-1510
} // KINEO-ADS-FIEL-4-1510

// ── acompanhamento de um plano ────────────────────────────────────────────────────────────────────────────────────
async function pollOne(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow): Promise<void> {
  const ctx = { userId: order.user_id, orderId: order.id }
  switch (row.status) {
    case 'pending':
    case 'image_done': {
      // Carimbo de envio sem desfecho (a lambda morreu entre o carimbo e o POST): ambíguo vencido depois de 20 min.
      const claim = row.status === 'pending' && row.source === 'generated_scene' && !row.image_url ? row.image_submit_claimed_at : row.submit_claimed_at
      if (claim && ageMs(claim) > ADS_V2_AMBIGUOUS_MAX_MS) await failShot(admin, row, [row.status], 'claim_without_outcome', 'transport_timeout_5xx')
      return
    }
    case 'ambiguous': {
      if (ageMs(row.updated_at) > ADS_V2_AMBIGUOUS_MAX_MS) await failShot(admin, row, ['ambiguous'], `${row.reason ?? 'ambiguous'}_expired`, 'transport_timeout_5xx')
      return
    }
    case 'image_submitted': {
      if (!row.image_request_id) return
      const p = await pollSceneImage(row.image_request_id, ctx)
      if (p.state === 'done' && p.url) {
        if (inHandTagOf(order, row.idx)) { await finishInHandImage(admin, order, row, p.url); return } // KINEO-ADS-PRODUTO-NA-MAO-1610 — o juiz do rótulo antes de virar vídeo
        const pv = row.kind === ADS_V2_PRESENTER_KIND ? await presenterV2Of(order) : null // KINEO-APRESENTADOR-V2-1710
        if (pv) { await finishPresenterV2Image(admin, order, row, p.urls && p.urls.length > 0 ? p.urls : [p.url], pv); return } // KINEO-APRESENTADOR-V2-1710 — as 4 opções: cópia, "frasco e caixa", a melhor
        const lock = adsV2LockOf(order, row) // KINEO-ADS-FIEL-1510 — cena de produto: o recorte REAL colado antes de virar vídeo
        if (lock && (await finishLockedImage(admin, order, row, lock, p.url)) === 'done') return // KINEO-ADS-FIEL-1510
        const stored = await persistSceneImage({ userId: order.user_id, orderId: order.id, idx: row.idx, attempt: row.attempt, falUrl: p.url })
        if (stored) await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: stored })
        else if (ageMs(row.updated_at) > ADS_V2_COPY_MAX_MS) await failShot(admin, row, ['image_submitted'], 'image_copy_failed', 'unknown')
      } else if (p.state === 'failed') {
        await failShot(admin, row, ['image_submitted'], 'image_provider_failed', 'unknown')
      } else if (ageMs(row.image_submit_claimed_at ?? row.updated_at) > (row.kind === ADS_V2_PRESENTER_KIND ? Math.max(ADS_V2_SHOT_STUCK_MS, cenaUgcAttemptDeadline(row)) : ADS_V2_FAST_IMAGE_STUCK_MS)) { // KINEO-ADS-FIEL-1510 — prazo curto da imagem (o ator mantém o de antes) // KINEO-ADS-CENA-2110
        if (await markShot(admin, row, ['image_submitted'], { status: 'stuck', reason: 'image_stuck', reason_class: 'unknown' })) cancelAbandoned(row, 'image') // KINEO-ADS-FIEL-1510 — na fila, a fal não cobra
      }
      return
    }
    case 'submitted': {
      let falUrl = row.fal_url
      if (!falUrl) {
        if (!row.request_id || !row.engine) return
        const p = await pollFalJob(ADS_V2_ENGINES[row.engine].slug, row.request_id, 'video', ctx)
        if (p.state === 'failed') { await failShot(admin, row, ['submitted'], 'provider_failed', 'unknown'); return }
        if (p.state !== 'done' || !p.url) {
          const ihLate = inHandTagOf(order, row.idx) // KINEO-ADS-MAO-AJUSTE-1610 — o plano "produto na mão" tem prazo próprio no Kling
          const late = ageMs(row.submitted_at ?? row.updated_at) > (row.kind === ADS_V2_PRESENTER_KIND ? Math.max(ADS_V2_SHOT_STUCK_MS, cenaUgcAttemptDeadline(row)) : ihLate && row.engine === 'kling_o3' ? ADS_V2_IN_HAND_VIDEO_STUCK_MS : ADS_V2_FAST_VIDEO_STUCK_MS) // KINEO-ADS-FIEL-1510 — prazo curto por tentativa (o ator mantém o de antes) · KINEO-ADS-MAO-AJUSTE-1610 — Kling do produto na mão: 5 min // KINEO-ADS-CENA-2110
          const again = late && ihLate ? await pollFalJob(ADS_V2_ENGINES[row.engine].slug, row.request_id, 'video', ctx) : null // KINEO-ADS-MAO-AJUSTE-1610 — ANTES do "travado", a fal de novo: COMPLETED = usa o clipe (no T1 pagamos 5 e usamos 1)
          if (again?.state === 'failed') { await failShot(admin, row, ['submitted'], 'provider_failed', 'unknown'); return } // KINEO-ADS-MAO-AJUSTE-1610
          if (again?.state !== 'done' || !again.url) { // KINEO-ADS-MAO-AJUSTE-1610 — nem pronto na 2ª consulta: o travado de sempre
            if (late && (await markShot(admin, row, ['submitted'], { status: 'stuck', reason: 'shot_stuck', reason_class: 'unknown' }))) cancelAbandoned(row, 'video') // KINEO-ADS-FIEL-1510 — job na fila é cancelado
            return
          } // KINEO-ADS-MAO-AJUSTE-1610
          falUrl = again.url // KINEO-ADS-MAO-AJUSTE-1610 — o clipe que ficou pronto no limite do prazo
        } else falUrl = p.url // KINEO-ADS-MAO-AJUSTE-1610 — era `falUrl = p.url` depois do if
        await markShot(admin, row, ['submitted'], { fal_url: falUrl, fal_done_at: nowIso() })
      }
      // A URL da fal expira: o plano só fica 'done' com a cópia no NOSSO bucket e a duração medida no mvhd.
      const copy = await persistShotClip({ userId: order.user_id, orderId: order.id, idx: row.idx, attempt: row.attempt, falUrl })
      if (copy) {
        const need = (num(row.cut_start) ?? 0) + (num(row.cut_seconds) ?? 0) + 0.25
        if (copy.measuredSeconds + 1e-6 < need) {
          await failShot(admin, row, ['submitted'], `clip_too_short:${copy.measuredSeconds}<${need}`, 'unknown')
          return
        }
        await markShot(admin, row, ['submitted'], { status: 'done', stored_url: copy.storedUrl, measured_seconds: copy.measuredSeconds, reason: null })
      } else if (ageMs(row.fal_done_at ?? nowIso()) > ADS_V2_COPY_MAX_MS) {
        await failShot(admin, row, ['submitted'], 'clip_copy_failed', 'unknown')
      }
      return
    }
    default:
      return
  }
}

/**
 * Plano que falhou por culpa do fornecedor ganha nova tentativa SEM cobrar (2ª no principal, 3ª no H3). Devolve o
 * motivo terminal quando não há mais tentativa (o pedido inteiro falha e estorna).
 */
async function retryOrTerminal(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow, stills: { used: number } = { used: 0 }): Promise<string | null> { // KINEO-ADS-FIEL-1510 — stills: fotos paradas já usadas no pedido
  // KINEO-ADS-CENA-2110 — UGC exige a pessoa: uma refação, depois falha terminal com estorno.
  if (row.kind === ADS_V2_PRESENTER_KIND) return retryPresenter(admin, order, row)
  if (row.kind === 'text') return `text_shot_${row.idx}_${row.status}` // nunca acontece: text nasce skipped_text
  if (row.kind === 'user_video') return `user_video_shot_${row.idx}_${row.status}` // nunca acontece: nasce 'done', sem IA
  // KINEO-ESTILOS-PRODUTO-2026-10-09 — o efeito da PixVerse sem acesso (404/403 de modelo = 'auth_model_access') NÃO mata o
  // anúncio: o plano segue para a próxima tentativa e cai na reserva H3, que é outro modelo. Saldo da fal (balance_quota)
  // continua terminal (a conta é a mesma para todos os motores).
  const effectAccess = row.engine === 'pixverse_effect' && row.reason_class === 'auth_model_access'
  if (row.reason_class && ADS_V2_NON_RETRY_CLASSES.includes(row.reason_class) && !effectAccess) return `shot_${row.idx}_${row.reason_class}`
  // Efeito sem acesso: pula direto para a reserva (repetir o mesmo modelo fechado só queima tempo).
  const nextAttempt = effectAccess ? Math.max(row.attempt + 1, ADS_V2_FALLBACK_FROM_ATTEMPT) : row.attempt + 1 // KINEO-ADS-FIEL-1510 — era `attempt`
  // KINEO-ADS-FIEL-1510 — PRAZO: a régua de antes enquanto couber em ~6,5 min desde o início; não cabendo, pula para a reserva H3;
  // KINEO-ADS-FIEL-1510 — nem ela cabendo (ou esgotada), a FOTO parada (até 2 por pedido). Sem foto parada: a régua de antes, e
  // KINEO-ADS-FIEL-1510 — esgotada = terminal com estorno, a MESMA frase de antes. Nada disto cobra o cliente.
  const styled = adsV2ShotEffect(order.plan, row.idx) !== null // KINEO-ADS-FIEL-1510
  const shotKind = row.kind // KINEO-ADS-FIEL-1510 — o tipo já sem o ator (o callback abaixo perde o estreitamento)
  const stillUrl = stillSourceOf(order, row) // KINEO-ADS-FIEL-1510
  const inHandVideo = !!inHandTagOf(order, row.idx) && row.engine === 'kling_o3' && !!row.image_url // KINEO-ADS-MAO-AJUSTE-1610 — o Kling do produto na mão falhou ou travou (a foto já existe)
  const fallbackIn = { nextAttempt, maxAttempts: ADS_V2_MAX_AUTO_ATTEMPTS, fallbackFrom: ADS_V2_FALLBACK_FROM_ATTEMPT, elapsedMs: ageMs(order.started_at), needsImage: row.source === 'generated_scene' && !row.image_url, stillsUsed: stills.used, canStill: !!stillUrl, skipPrincipal: (row.status === 'stuck' && row.reason === 'shot_stuck') || inHandVideo, route: (a: number) => routeShot(shotKind, order.tier, a, styled) } // KINEO-ADS-FIEL-1510 — vídeo preso no principal = direto à reserva · KINEO-ADS-MAO-AJUSTE-1610 — produto na mão: Kling falhou = plano B no H3 (sem 2º Kling)
  const step = inHandVideo ? adsV2FallbackStepTimed({ ...fallbackIn, typical: ADS_V2_IN_HAND_ENGINE_TYPICAL_MS, stillAtMs: ADS_V2_IN_HAND_STILL_AT_MS }) : adsV2FallbackStep(fallbackIn) // KINEO-ADS-MAO-AJUSTE-1610 — o prazo do produto na mão; os outros modos, a régua de sempre
  if (step.step === 'terminal') return `shot_${row.idx}_exhausted:${row.reason ?? row.status}` // KINEO-ADS-FIEL-1510 — a frase de antes
  if (step.step === 'still') { if (stillUrl && (await stillFallback(admin, order, row, stillUrl, `${row.status}:${row.reason ?? ''}`))) stills.used += 1; return null } // KINEO-ADS-FIEL-1510
  const attempt = step.attempt // KINEO-ADS-FIEL-1510
  const engine = routeShot(row.kind, order.tier, attempt, styled) // KINEO-ADS-FIEL-1510 — o mesmo routeShot de antes
  if (!engine) return `shot_${row.idx}_no_engine`
  // Cena criada cuja IMAGEM já saiu reaproveita a imagem (só o vídeo falhou); falha na imagem recomeça pela imagem.
  const keepImage = row.source === 'client_photo' || !!row.image_url
  const next = {
    order_id: order.id,
    idx: row.idx,
    attempt,
    role: row.role,
    kind: row.kind,
    source: row.source,
    source_footage_id: row.source_footage_id,
    image_url: keepImage ? row.image_url : null,
    engine,
    prompt: row.prompt,
    gen_seconds: ADS_V2_ENGINES[engine].genSeconds,
    cut_start: inHandVideo && engine === 'h3' ? ((await inHandLib())?.adsV2InHandH3CutStart(num(row.cut_seconds) ?? 0) ?? 0) : row.cut_start, // KINEO-ADS-MAO-AJUSTE-1610 — plano B no H3: só o começo, corte ≤ 2,5 s (depois o produto cresce)
    cut_seconds: row.cut_seconds,
    movement_variant: row.movement_variant,
    status: row.source === 'generated_scene' && keepImage ? 'image_done' : 'pending',
  }
  const ins = await admin.from('ads_v2_shots').upsert(next, { onConflict: 'order_id,idx,attempt', ignoreDuplicates: true }).select('id')
  if (!ins.error && Array.isArray(ins.data) && ins.data.length > 0) {
    await writeServerEvent({
      name: 'ads_v2_shot_retried',
      userId: order.user_id,
      path: '/lib/ads/v2Advance',
      metadata: { order_id: order.id, idx: row.idx, attempt, engine, previous_reason: row.reason, previous_class: row.reason_class, charged: false },
    })
    if (engine !== row.engine || step.skipped) await shotFallbackEvent(order, row, { to: engine, reason: step.skipped ? 'time_budget' : 'engine_fallback', next_attempt: attempt }) // KINEO-ADS-FIEL-1510
  }
  return null
}

/**
 * KINEO-ATOR-ANUNCIO-2026-10-09 — o ator que falhou ganha UMA 2ª tentativa sem cobrar (a foto pronta é reaproveitada; sem
 * KINEO-ADS-CENA-2110 — foto, recomeça pela foto). O prazo antigo repete UMA vez, com relógio novo e maior.
 * KINEO-ADS-CENA-2110 — falha terminal devolve motivo ao estorno do pedido; nunca entrega UGC sem pessoa.
 */
async function retryPresenter(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow): Promise<string | null> { // KINEO-ADS-CENA-2110
  const action = cenaUgcFailureAction(row) // KINEO-ADS-CENA-2110
  if (action === 'refund') return `ugc_presenter_failed:${row.reason ?? row.status}` // KINEO-ADS-CENA-2110
  if (action !== 'retry') return null // KINEO-ADS-CENA-2110
  const keepImage = !!row.image_url
  const next = {
    order_id: order.id,
    idx: row.idx,
    attempt: row.attempt + 1,
    role: row.role,
    kind: row.kind,
    source: row.source,
    source_footage_id: row.source_footage_id,
    image_url: keepImage ? row.image_url : null,
    engine: row.engine,
    prompt: row.prompt,
    gen_seconds: null,
    cut_start: row.cut_start,
    cut_seconds: row.cut_seconds,
    movement_variant: row.movement_variant,
    status: keepImage ? 'image_done' : 'pending',
  }
  const ins = await admin.from('ads_v2_shots').upsert(next, { onConflict: 'order_id,idx,attempt', ignoreDuplicates: true }).select('id')
  if (!ins.error && Array.isArray(ins.data) && ins.data.length > 0) {
    await writeServerEvent({
      name: 'ads_v2_shot_retried',
      userId: order.user_id,
      path: '/lib/ads/v2Advance',
      metadata: { order_id: order.id, idx: row.idx, attempt: next.attempt, engine: row.engine, presenter: true, previous_reason: row.reason, previous_class: row.reason_class, charged: false },
    })
    await writeServerEvent({ name: 'ads_v2_ugc_retried', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, attempt: next.attempt, previous_reason: row.reason, deadline_ms: cenaUgcAttemptDeadline({ ...row, attempt: next.attempt }), charged: false } }) // KINEO-ADS-CENA-2110
  }
  return null
}

/**
 * KINEO-ATORES-IA-2026-10-13 — a voz da narração do pedido. Sem apresentador escolhido, ou apresentador de voz MiniMax =
 * synthesizeTtsFallback(texto, ctx), a chamada de sempre. Apresentador de voz ElevenLabs = a voz DELE (synthesizeElevenVoice,
 * o corpo da rota /audio). `fallbackToDefault`: no passo do ATOR é false (voz de mulher na boca de um homem é pior que esperar:
 * a próxima volta tenta de novo e, no prazo do ator, o anúncio sai sem ele); na MONTAGEM é true (lá o ator já desistiu — senão
 * a voz estaria gravada — e a narração sai na voz de sempre em vez de travar o pedido).
 */
async function adsV2NarrationVoice(order: AdsV2OrderRow, text: string, fallbackToDefault: boolean, speedOverride?: number): Promise<Buffer> { // KINEO-APRESENTADOR-V2-AJUSTE-1710 — + speedOverride (só a voz do v2 com voice id: a voz medida que passou do alvo)
  const ctx = { userId: order.user_id, generationId: order.generation_id }
  if (adsV2CloseRealOf(order.plan)) { // KINEO-CLOSE-REAL-1910 — o Close real fala na voz por língua do apresentador v2 (PT-BR: Portuguese_ConfidentWoman na speech-2.8-hd); falhou = a voz de sempre
    try { // KINEO-CLOSE-REAL-1910
      const lib = await presenterV2Lib() // KINEO-CLOSE-REAL-1910
      const cv = lib ? lib.adsV2PresenterV2VoiceFor(narrationLanguage(order.language) ?? 'en', 'woman') : null // KINEO-CLOSE-REAL-1910
      if (cv && cv.engine === 'minimax') { const vm = await import('@/lib/avatar/voice'); return await vm.synthesizeWithVoice({ voiceId: cv.voiceId, text, model: cv.model, languageBoost: cv.languageBoost, speed: cv.speed }) } // KINEO-CLOSE-REAL-1910
    } catch (e) { console.warn(`[ads-v2] voz do Close real falhou order=${order.id} (segue a de sempre):`, e instanceof Error ? e.message : String(e)) } // KINEO-CLOSE-REAL-1910
    return synthesizeTtsFallback(text, ctx) // KINEO-CLOSE-REAL-1910
  } // KINEO-CLOSE-REAL-1910
  const pv = await presenterV2Of(order) // KINEO-APRESENTADOR-V2-1710 — a voz do apresentador v2 por língua (PT-BR: Portuguese_ConfidentWoman na speech-2.8-hd); 'current' = a de sempre (abaixo)
  const v2Voice = pv ? pv.lib.adsV2PresenterV2VoiceFor(narrationLanguage(order.language) ?? 'en', pv.v2.gender) : null // KINEO-APRESENTADOR-V2-1710
  if (v2Voice && v2Voice.engine === 'minimax') { // KINEO-APRESENTADOR-V2-1710
    try { // KINEO-APRESENTADOR-V2-1710
      const vm = await import('@/lib/avatar/voice') // KINEO-APRESENTADOR-V2-1710 — a síntese com voice id (o /audio e a TTS da casa não mudam)
      return await vm.synthesizeWithVoice({ voiceId: v2Voice.voiceId, text, model: v2Voice.model, languageBoost: v2Voice.languageBoost, speed: typeof speedOverride === 'number' && speedOverride > 0 ? speedOverride : v2Voice.speed }) // KINEO-APRESENTADOR-V2-1710 · KINEO-APRESENTADOR-V2-AJUSTE-1710 — a aceleração do ajuste (até 1,08) ou a voz de sempre
    } catch (e) { // KINEO-APRESENTADOR-V2-1710
      console.warn(`[ads-v2] voz ${v2Voice.voiceId} do apresentador v2 falhou order=${order.id}:`, e instanceof Error ? e.message : String(e)) // KINEO-APRESENTADOR-V2-1710
      if (!fallbackToDefault) throw e // KINEO-APRESENTADOR-V2-1710 — no passo do ator: tenta de novo na próxima volta; na montagem: a voz de sempre
    } // KINEO-APRESENTADOR-V2-1710
  } // KINEO-APRESENTADOR-V2-1710
  const presenterId = adsV2PresenterPlanOf(order.plan)?.presenterId ?? null
  const voice = presenterId ? adsV2PresenterVoiceOf(presenterId) : null
  if (!voice || voice.engine !== 'eleven') return synthesizeTtsFallback(text, ctx)
  try {
    return await synthesizeElevenVoice(text, voice.voice, ctx)
  } catch (e) {
    console.warn(`[ads-v2] voz ${voice.voice} do apresentador ${presenterId} falhou order=${order.id}:`, e instanceof Error ? e.message : String(e))
    if (!fallbackToDefault) throw e
    return synthesizeTtsFallback(text, ctx)
  }
}
/** KINEO-CLOSE-REAL-V3-1910 — a voz do Close real (a MESMA de adsV2NarrationVoice: por língua do apresentador v2; PT-BR = Portuguese_ConfidentWoman; falhou = a de sempre), para o áudio cedo (lib/ads/v2AudioCedo.ts) não gravar a voz padrão antes da montagem. */
export function adsV2CloseRealNarrationVoice(order: AdsV2OrderRow, text: string): Promise<Buffer> { return adsV2NarrationVoice(order, text, true) } // KINEO-CLOSE-REAL-V3-1910
// KINEO-APRESENTADOR-OLHOS-1910 — o voice_id que a voz do pedido usa (para auditoria no evento da montagem), pela MESMA árvore de adsV2NarrationVoice: Close real = a voz por língua
// KINEO-APRESENTADOR-OLHOS-1910 — (mulher); apresentador v2 = a da tabela por língua+gênero, senão a do retrato; ator de antes = a ElevenLabs dele; resto = a MiniMax padrão. Nunca lança ('unknown').
async function adsV2NarrationVoiceId(order: AdsV2OrderRow): Promise<string> { // KINEO-APRESENTADOR-OLHOS-1910
  try { // KINEO-APRESENTADOR-OLHOS-1910
    const lang = narrationLanguage(order.language) ?? 'en' // KINEO-APRESENTADOR-OLHOS-1910
    if (adsV2CloseRealOf(order.plan)) { const lib = await presenterV2Lib(); return lib ? lib.adsV2PresenterV2VoiceIdOf(lang, 'woman', null) : 'minimax:default' } // KINEO-APRESENTADOR-OLHOS-1910
    const presenterId = adsV2PresenterPlanOf(order.plan)?.presenterId ?? null // KINEO-APRESENTADOR-OLHOS-1910
    const entryVoice = presenterId ? adsV2PresenterVoiceOf(presenterId) : null // KINEO-APRESENTADOR-OLHOS-1910
    const pv = await presenterV2Of(order) // KINEO-APRESENTADOR-OLHOS-1910
    if (pv) return pv.lib.adsV2PresenterV2VoiceIdOf(lang, pv.v2.gender, entryVoice) // KINEO-APRESENTADOR-OLHOS-1910
    return entryVoice && entryVoice.engine === 'eleven' ? `eleven:${entryVoice.voice}` : 'minimax:default' // KINEO-APRESENTADOR-OLHOS-1910
  } catch { return 'unknown' } // KINEO-APRESENTADOR-OLHOS-1910
} // KINEO-APRESENTADOR-OLHOS-1910

/**
 * KINEO-APRESENTADOR-V2-AJUSTE-1710 — a voz MEDIDA do apresentador v2 passou do alvo (~10,5 s)? Re-sintetiza UMA vez com a decisão pura (adsV2PresenterV2VoiceFit:
 * KINEO-APRESENTADOR-V2-AJUSTE-1710 — speed até 1,08, ou tirar a frase do meio mais longa e, se precisar, speed). null = coube, não é v2, ou a re-síntese falhou
 * KINEO-APRESENTADOR-V2-AJUSTE-1710 — (fica a voz medida: passar do alvo é melhor que travar o pedido). Nunca lança.
 */
async function presenterV2FitVoice(order: AdsV2OrderRow, narration: string, language: string, voiceSeconds: number): Promise<{ buf: Buffer; voiceSeconds: number; plan: AdsV2StoredPlan } | null> { // KINEO-APRESENTADOR-V2-AJUSTE-1710
  try { // KINEO-APRESENTADOR-V2-AJUSTE-1710
    const pv = await presenterV2Of(order) // KINEO-APRESENTADOR-V2-AJUSTE-1710
    if (!pv || !order.plan) return null // KINEO-APRESENTADOR-V2-AJUSTE-1710
    const voice = pv.lib.adsV2PresenterV2VoiceFor(narrationLanguage(order.language) ?? 'en', pv.v2.gender) // KINEO-APRESENTADOR-V2-AJUSTE-1710
    const fit = pv.lib.adsV2PresenterV2VoiceFit({ seconds: voiceSeconds, text: narration, canSpeed: voice.engine === 'minimax', language: narrationLanguage(order.language) ?? 'en' }) // KINEO-APRESENTADOR-V2-AJUSTE-1710 — só a voz com voice id aceita speed · KINEO-ADS-BOLA-2110 — + a língua: a voz CURTA ganha a frase a mais na língua do anúncio
    const record = pv.lib.adsV2PresenterV2VoiceFitRecord(fit, { seconds: voiceSeconds, text: narration }) // KINEO-APRESENTADOR-V2-AJUSTE-1710
    if (fit.action === 'ok' || !record) return null // KINEO-APRESENTADOR-V2-AJUSTE-1710
    const buf = await adsV2NarrationVoice(order, speakableForTts(adsV2NarrationForTts(fit.text, adsV2PronounceOf(order.brief)), language), false, fit.speed !== 1 ? fit.speed : undefined) // KINEO-APRESENTADOR-V2-AJUSTE-1710
    const presenter = adsV2PresenterPlanOf(order.plan) // KINEO-APRESENTADOR-V2-AJUSTE-1710
