  let overlayK = 1 // KINEO-ADS-FIEL-2-1510
  let fitInfo: Record<string, unknown> | null = null // KINEO-ADS-FIEL-2-1510
  if (!presenterSource && !closeRealSource) { // KINEO-ADS-FIEL-2-1510 · KINEO-CLOSE-REAL-1910 — o Close real tem a linha do tempo dele; era: if (!presenterSource) {
    const shotsBefore = shotsSeconds // KINEO-ADS-FIEL-2-1510
    const cuts0 = montageShots.map((s) => s.cutSeconds) // KINEO-ADS-FIEL-2-1510
    let fit = adsV2FitTimeline({ targetSeconds: order.seconds, cuts: cuts0, voiceSeconds: voiceSeconds ?? null, voiceStart: ADS_V2_VOICE_START }) // KINEO-ADS-FIEL-2-1510
    let spokenText = narration // KINEO-ADS-FIEL-2-1510
    let resynth = 0 // KINEO-ADS-FIEL-2-1510
    while (spokenText && voiceSeconds && !fit.voiceFits && resynth < 2) { // KINEO-ADS-FIEL-2-1510
      const words = spokenText.split(/\s+/).filter(Boolean).length // KINEO-ADS-FIEL-2-1510
      const shorter = adsV2ShortenNarration(spokenText, adsV2NarrationWordBudget(words, voiceSeconds, fit.voiceMaxSeconds)) // KINEO-ADS-FIEL-2-1510
      if (shorter === spokenText) break // KINEO-ADS-FIEL-2-1510 — nada mais a tirar sem reescrever
      resynth += 1 // KINEO-ADS-FIEL-2-1510
      const buf = await adsV2NarrationVoice(order, speakableForTts(adsV2NarrationForTts(shorter, adsV2PronounceOf(order.brief)), language), true) // KINEO-ADS-FIEL-2-1510 — a mesma voz, a mesma pronúncia
      voiceSeconds = Math.round(estimateMp3DurationSeconds(buf) * 1000) / 1000 // KINEO-ADS-FIEL-2-1510
      voiceUrl = await uploadVoiceoverToSupabase(order.user_id, buf) // KINEO-ADS-FIEL-2-1510
      spokenText = shorter // KINEO-ADS-FIEL-2-1510
      await admin.from('ads_v2_orders').update({ voice_url: voiceUrl, voice_seconds: voiceSeconds, plan: { ...plan, narration: shorter } }).eq('id', order.id) // KINEO-ADS-FIEL-2-1510 — o roteiro gravado = o que a voz fala
      fit = adsV2FitTimeline({ targetSeconds: order.seconds, cuts: cuts0, voiceSeconds, voiceStart: ADS_V2_VOICE_START }) // KINEO-ADS-FIEL-2-1510
    } // KINEO-ADS-FIEL-2-1510
    if (fit.scaled) { montageShots.forEach((s, k) => { s.cutSeconds = fit.cuts[k] }); shotsSeconds = fit.shotsSeconds; overlayK = shotsBefore > 0 ? fit.shotsSeconds / shotsBefore : 1 } // KINEO-ADS-FIEL-2-1510
    fitInfo = { target: order.seconds, scaled: fit.scaled, voice_fits: fit.voiceFits, resynth, narration_words: spokenText ? spokenText.split(/\s+/).filter(Boolean).length : 0 } // KINEO-ADS-FIEL-2-1510
  } // KINEO-ADS-FIEL-2-1510
  if (voiceSeconds && !presenterSource && !closeRealSource) { // KINEO-CLOSE-REAL-1910 — era: if (voiceSeconds && !presenterSource) {
    const voiceEnd = ADS_V2_VOICE_START + voiceSeconds + 0.2
    cardSeconds = Math.max(cardSeconds, Math.round((voiceEnd - shotsSeconds) * 1000) / 1000)
    if (cardSeconds > ADS_V2_CARD_MAX_SECONDS) {
      await failAdsV2Order(admin, order, `voice_too_long:${voiceSeconds}`, '/lib/ads/v2Advance')
      return
    }
  }
  const out = renderOutputSpecFor(adsV2PlanFormat(plan)) // KINEO-ADS-MELHORIAS-1410 — o quadro do formato (9:16 = o de sempre, com o perfil de custo)
  let source: Record<string, unknown>
  try {
    // KINEO-ATOR-ANUNCIO-2026-10-09 — com o ator pronto, a montagem dele; senão, a de sempre (abaixo, intocada).
    source = closeRealSource ?? presenterSource ?? buildAdV2Source({ // KINEO-CLOSE-REAL-1910 — o Close real primeiro; era: source = presenterSource ?? buildAdV2Source({
      width: out.width,
      height: out.height,
      shots: montageShots,
      overlays: (plan.overlays ?? []).filter((o) => o && typeof o.text === 'string' && o.text.trim()).map((o) => (overlayK === 1 ? { text: o.text, start: o.start, end: o.end } : { text: o.text, start: Math.round(o.start * overlayK * 1000) / 1000, end: Math.min(shotsSeconds, Math.round(o.end * overlayK * 1000) / 1000) })), // KINEO-ADS-FIEL-2-1510 — planos encolhidos = as frases na mesma proporção
      fontFamily: captionFontFor(language),
      cardUrl: order.card_url,
      cardSeconds,
      musicUrl,
      musicTrimStart: adsV2MusicTrimStart(musicUrl),
      voiceUrl,
      voiceSeconds,
      // KINEO-ADS-3VAR-COR-2026-09-30 — a cor do look na montagem (null fora das 3 variações).
      tint: variationTintOf(order.brief),
      // KINEO-ANUNCIO-CONSERTOS-2026-10-12 — anúncio com foto de PRODUTO: frases no terço de baixo (não cobrem o rótulo).
      ...(adsV2ProductOverlays(order.photos) ? { overlayPlacement: 'lower_third' as const } : {}),
    })
  } catch (e) {
    await failAdsV2Order(admin, order, `montage_invalid:${e instanceof Error ? e.message : String(e)}`, '/lib/ads/v2Advance')
    return
  }
  source = cenaApplyCaptions({ source, text: narration, seconds: voiceSeconds, start: presenterSource ? 0 : ADS_V2_VOICE_START, legacyTextTrack: closeRealSource || presenterV2 ? 5 : 4, fontFamily: captionFontFor(language) }) // KINEO-ADS-CENA-2110
  // KINEO-HOME-3-CARDS-1910 — a amostra grátis fora do Close real (a do card UGC, com a pessoa, ou o anúncio de reserva dela se o ator desistir) leva a MESMA
  // KINEO-HOME-3-CARDS-1910 — marca-d'água do Close real (que já a desenha): um texto por cima de tudo, do 0 ao fim. Pago nunca passa aqui (chave 'adsv2').
  if (isAdsSampleRef(order.billing_ref) && !closeRealSource) source = adsSampleWatermarkSource(source, { text: ADS_V2_CLOSE_REAL_WATERMARK, fontFamily: captionFontFor(language), width: Number(source.width) || out.width }) // KINEO-HOME-3-CARDS-1910
  // 4. Carimbo ANTES do POST (só quem ainda segura a trava): com ele e sem id, o envio é ambíguo e nunca se repete.
  const stamp = await admin
    .from('ads_v2_orders')
    .update({ assembly_submit_at: nowIso() })
    .eq('id', order.id)
    .eq('status', 'assembling')
    .eq('assembly_lease_at', leaseToken)
    .is('creatomate_render_id', null)
    .is('assembly_submit_at', null)
    .select('id')
    .maybeSingle()
  if (stamp.error || !stamp.data) return
  let renderId: string
  try {
    renderId = await submitCreatomateRender(source)
  } catch (e) {
    if (e instanceof CreatomateSubmitError && e.ambiguous) {
      console.warn(`[ads-v2] Creatomate ambíguo order=${order.id} — sem reenvio; o prazo decide`)
      return
    }
    await failAdsV2Order(admin, order, `creatomate_rejected:${e instanceof Error ? e.message.slice(0, 160) : String(e)}`, '/lib/ads/v2Advance')
    return
  }
  // 5. O id do render é a PRIMEIRA coisa gravada depois do POST (uma repetição se a escrita falhar).
  const write = () => admin.from('ads_v2_orders').update({ creatomate_render_id: renderId }).eq('id', order.id).is('creatomate_render_id', null).select('id').maybeSingle()
  let w = await write()
  if (w.error) w = await write()
  if (w.error) console.error(`[ads-v2] creatomate_render_id NÃO gravado order=${order.id} render=${renderId}`)
  const voiceId = await adsV2NarrationVoiceId(order) // KINEO-APRESENTADOR-OLHOS-1910 — a voz que o anúncio usou (auditoria: a amostra da tela tem de bater com ela)
  await writeServerEvent({
    name: 'ads_v2_assembling',
    userId: order.user_id,
    path: '/lib/ads/v2Advance',
    metadata: { order_id: order.id, creatomate_render_id: renderId, voice_id: voiceId, shots: montageShots.length, card_seconds: cardSeconds, voice_seconds: voiceSeconds, music: Boolean(musicUrl), music_source: musicUrl ? musicSource : 'none', ...(presenterV2?.v2?.voiceFit ? { presenter_v2_voice_fit: presenterV2.v2.voiceFit } : {}), total_seconds: presenterSource ? Number(presenterSource.duration) : Math.round((shotsSeconds + cardSeconds) * 1000) / 1000, presenter: Boolean(presenterSource), presenter_fallback: presenterMiss, ...(fitInfo ? { fit: fitInfo } : {}) }, // KINEO-ADS-FIEL-2-1510 — o encaixe na duração // KINEO-APRESENTADOR-V2-AJUSTE-1710 — + music_source (lyria / library = a reserva automática / library_swap / stored) e o ajuste da voz do v2 · KINEO-APRESENTADOR-OLHOS-1910 — + voice_id
  })
  if (closeRealSource) await writeServerEvent({ name: 'ads_v2_close_real_assembled', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, creatomate_render_id: renderId, hero: closeRealHero, sample: isAdsSampleRef(order.billing_ref), watermark: isAdsSampleRef(order.billing_ref), photos: closeRealPlan?.photos.length ?? 0, total_seconds: Number(closeRealSource.duration), voice_seconds: voiceSeconds, voice_id: voiceId, music_source: musicUrl ? musicSource : 'none' } }) // KINEO-CLOSE-REAL-1910 — a medição do formato (gancho recortado ou foto real, amostra com marca, duração real) · KINEO-APRESENTADOR-OLHOS-1910 — + voice_id
}

async function pollAssembly(admin: SupabaseClient, order: AdsV2OrderRow): Promise<void> {
  const renderId = order.creatomate_render_id
  if (!renderId || !order.billing_ref) return
  let st
  try {
    st = await pollCreatomateRender(renderId)
  } catch {
    return // consulta falhou: tenta na próxima volta
  }
  if (st.status === 'failed' || st.status === 'cancelled') {
    await failAdsV2Order(admin, order, `creatomate_${st.status}:${(st.error ?? '').slice(0, 120)}`, '/lib/ads/v2Advance')
    return
  }
  if (st.status !== 'succeeded' || !st.url) {
    if (ageMs(order.assembly_submit_at) > ADS_V2_CREATOMATE_MAX_MS) await failAdsV2Order(admin, order, 'creatomate_stuck', '/lib/ads/v2Advance')
    return
  }
  // Cópia para o nosso bucket com a chave de cobrança como render_id (a mesma do videos.render_id).
  const assets = await persistRenderAssets({ userId: order.user_id, renderId: order.billing_ref, videoUrl: st.url, snapshotUrl: st.snapshotUrl, downloadTimeoutMs: 60_000 })
  const business = businessName(order)
  const seconds = assets.measuredSeconds ?? st.durationSeconds ?? (order.plan?.totalSeconds ?? order.seconds)
  const row = {
    user_id: order.user_id,
    status: 'completed',
    video_url: assets.videoUrl,
    thumbnail_url: assets.thumbnailUrl ?? null,
    render_id: order.billing_ref,
    topic: `${business} · Studio Ads`.slice(0, 200),
    title: business,
    platform: 'Studio Ads',
    duration: Math.round(Number(seconds) || order.seconds),
    quality_mode: ADS_V2_QUALITY,
    credits_used: order.credits_charged,
    ...(order.plan?.narration ? { script: order.plan.narration } : {}),
  }
  // REVISÃO 28/09 (dinheiro): o id do vídeo é RESERVADO no pedido ANTES da linha em videos. failAdsV2Order (prazo do
  // pedido, Creatomate preso) e a varredura exigem video_id nulo — com a reserva, ninguém estorna o filme que está
  // entrando na biblioteca do cliente. Linha em videos que não entra: a reserva é SOLTA (o prazo volta a decidir).
  let reserved = order.video_id
  if (!reserved) {
    const fresh = randomUUID()
    const claim = await admin.from('ads_v2_orders').update({ video_id: fresh }).eq('id', order.id).eq('status', 'assembling').is('video_id', null).select('id').maybeSingle()
    if (claim.error || !claim.data) return
    reserved = fresh
  }
  let videoId: string | null = null
  const ins = await admin.from('videos').insert({ id: reserved, ...row }).select('id').maybeSingle()
  if (!ins.error && ins.data) videoId = String((ins.data as { id: string }).id)
  else if ((ins.error as { code?: string } | null)?.code === '23505') {
    const ex = await admin.from('videos').select('id').eq('render_id', order.billing_ref).eq('user_id', order.user_id).maybeSingle()
    videoId = ex.data ? String((ex.data as { id: string }).id) : null
  }
  if (!videoId) {
    console.error(`[ads-v2] insert em videos falhou order=${order.id}:`, ins.error?.message)
    await admin.from('ads_v2_orders').update({ video_id: null }).eq('id', order.id).eq('status', 'assembling').eq('video_id', reserved)
    return
  }
  const won = await admin
    .from('ads_v2_orders')
    .update({ status: 'delivered', video_id: videoId, delivered_at: nowIso(), error: null })
    .eq('id', order.id)
    .eq('status', 'assembling')
    .eq('video_id', reserved)
    .select('id')
    .maybeSingle()
  if (!won.error && won.data) {
    await writeServerEvent({
      name: 'ads_v2_delivered',
      userId: order.user_id,
      path: '/lib/ads/v2Advance',
      metadata: {
        order_id: order.id,
        video_id: videoId,
        billing_ref: order.billing_ref,
        tier: order.tier,
        seconds: order.seconds,
        credits: order.credits_charged,
        measured_seconds: assets.measuredSeconds,
        copied: assets.videoUrl !== st.url,
        retake: Boolean(order.parent_order_id),
        minutes: Math.round(ageMs(order.started_at) / 6000) / 10,
      },
    })
  }
}

async function stepAssembly(admin: SupabaseClient, order: AdsV2OrderRow, justClaimedToken: string | null, shots: AdsV2ShotRow[]): Promise<void> {
  if (order.creatomate_render_id) return pollAssembly(admin, order)
  if (order.assembly_submit_at) {
    // POST ao Creatomate sem id gravado: AMBÍGUO. Nunca reenviar; passado o prazo, falha com estorno.
    if (ageMs(order.assembly_submit_at) > ADS_V2_CREATOMATE_AMBIGUOUS_MS) await failAdsV2Order(admin, order, 'creatomate_submit_ambiguous', '/lib/ads/v2Advance')
    return
  }
  let token = justClaimedToken
  if (!token) {
    // Trava de preparo vencida (a lambda anterior morreu antes do carimbo): retoma com UPDATE condicional.
    if (order.assembly_lease_at && ageMs(order.assembly_lease_at) < ADS_V2_ASSEMBLY_LEASE_MS) return
    const fresh = nowIso()
    let q = admin.from('ads_v2_orders').update({ assembly_lease_at: fresh }).eq('id', order.id).eq('status', 'assembling').is('creatomate_render_id', null).is('assembly_submit_at', null)
    q = order.assembly_lease_at ? q.eq('assembly_lease_at', order.assembly_lease_at) : q.is('assembly_lease_at', null)
    const r = await q.select('id').maybeSingle()
    if (r.error || !r.data) return
    token = fresh
  }
  try {
    await prepareAndSubmit(admin, order, token, shots)
  } catch (e) {
    // Voz/música falharam (ex.: saldo da fal): a próxima volta retoma depois da trava; o prazo do pedido decide.
    console.warn(`[ads-v2] preparo da montagem falhou order=${order.id}:`, e instanceof Error ? e.message : String(e))
  }
}

// ── avanço do pedido ──────────────────────────────────────────────────────────────────────────────────────────────
export interface AdsV2ShotView {
  idx: number
  kind: string
  source: string
  attempt: number
  state: 'ready' | 'working' | 'failed'
  status: string
  url: string | null
  retake_credits: number
  /** KINEO-ADS-MELHORIAS-1410 — o plano é a foto REAL do produto (sem IA). Ausente = plano de sempre. */
  packshot?: true
  /** KINEO-ADS-REFACAO-ATOR-1410 — o plano é uma PESSOA DE IA segurando o produto (a tela diz "Pessoa de IA"). Ausente = plano de sempre. */
  ai_person?: true // KINEO-ADS-REFACAO-ATOR-1410
}
export interface AdsV2OrderView {
  narration_used?: string; quality_notes?: AjusteQualityNote[] // KINEO-ADS-CENA-SEGUE-2110 — only the AJUSTE scene engine.
  order_id: string
  status: AdsV2OrderRow['status']
  tier: AdsV2Tier
  seconds: number
  credits: number
  video_id: string | null
  error: string | null
  parent_order_id: string | null
  shots: AdsV2ShotView[]
  /** KINEO-ATOR-ANUNCIO-2026-10-09 — só no pedido com ator: o estado dele (desistiu = 'skipped': o anúncio sai sem ele). */
  presenter?: { state: 'ready' | 'working' | 'skipped'; status: string; attempt: number }
}

export function adsV2View(order: AdsV2OrderRow, shots: readonly AdsV2ShotRow[]): AdsV2OrderView {
  return {
    ...ajusteReviewOf(order.plan), // KINEO-ADS-CENA-SEGUE-2110 — status and order GETs share the persisted evidence.
    order_id: order.id,
    status: order.status,
    tier: order.tier,
    seconds: order.seconds,
    credits: order.credits_charged,
    video_id: order.video_id,
    error: order.status === 'failed' ? (order.error ?? 'failed') : null,
    parent_order_id: order.parent_order_id,
    ...presenterView(shots),
    shots: latestShots(shots).filter(isAdsV2PlanShotRow).map((r) => ({
      idx: r.idx,
      kind: r.kind,
      source: r.source,
      attempt: r.attempt,
      state: READY.has(r.status) ? 'ready' : r.status === 'failed' || r.status === 'stuck' ? 'failed' : 'working',
      status: r.status,
      url: READY.has(r.status) ? r.stored_url : null,
      retake_credits: r.kind === 'text' || r.kind === 'user_video' ? 0 : adsV2RetakeCredits(r.kind, order.tier),
      ...(r.kind === 'text' && adsV2IsPackshot(order.plan, r.idx) ? { packshot: true as const } : {}), // KINEO-ADS-MELHORIAS-1410 — a tela diz "Sua foto real"
      ...(adsV2IsPresenterHolds(order.plan, r.idx) ? { ai_person: true as const } : {}), // KINEO-ADS-REFACAO-ATOR-1410 — a tela diz "Pessoa de IA"
    })),
  }
}

/** KINEO-ATOR-ANUNCIO-2026-10-09 — a vista do ator (sem ator = nenhuma chave nova: a vista de antes, chave por chave). */
function presenterView(shots: readonly AdsV2ShotRow[]): { presenter?: NonNullable<AdsV2OrderView['presenter']> } {
  const r = latestShots(shots).find(isAdsV2PresenterRow)
  if (!r) return {}
  const state = READY.has(r.status) ? 'ready' : 'working' // KINEO-ADS-CENA-2110
  return { presenter: { state, status: r.status, attempt: r.attempt } }
}

/**
 * Um passo do pedido. Idempotente e seguro em paralelo (tela + cron). Nunca lança; devolve a vista do pedido.
 * `deadlineMs` limita os envios novos (o chamador tem teto de função).
 */
export async function advanceAdsV2Order(admin: SupabaseClient, orderId: string, opts: { deadlineMs: number }): Promise<AdsV2OrderView | null> {
  try {
    let { order } = await loadAdsV2Order(admin, orderId)
    if (!order) return null
    if (order.status === 'generating' || order.status === 'assembling') {
      if (ageMs(order.started_at) > ADS_V2_ORDER_MAX_MS && !order.video_id) {
        await failAdsV2Order(admin, order, 'order_timeout', '/lib/ads/v2Advance')
      } else if (order.status === 'generating') {
        await stepGenerating(admin, order, opts.deadlineMs)
      } else {
        const shots = (await loadAdsV2Shots(admin, order.id)) ?? []
        await stepAssembly(admin, order, null, shots)
      }
    }
    order = (await loadAdsV2Order(admin, orderId)).order
    if (!order) return null
    const shots = (await loadAdsV2Shots(admin, order.id)) ?? []
    return adsV2View(order, shots)
  } catch (e) {
    console.warn(`[ads-v2] avanço falhou order=${orderId}:`, e instanceof Error ? e.message : String(e))
    const { order } = await loadAdsV2Order(admin, orderId).catch(() => ({ order: null }))
    if (!order) return null
    return adsV2View(order, (await loadAdsV2Shots(admin, order.id).catch(() => null)) ?? [])
  }
}

async function stepGenerating(admin: SupabaseClient, order: AdsV2OrderRow, deadlineMs: number): Promise<void> {
  if ((order.plan as { cena?: { plan?: { marker?: string } } } | null)?.cena?.plan?.marker === 'KINEO-ADS-CENA-2110') { await (await import('@/lib/ads/cena/runtime')).advanceCenaOrder(admin, order, deadlineMs); return } // KINEO-ADS-CENA-2110 KINEO-ADS-CENA-95-2110 — prazo propagado ao canário; ausente = o corpo anterior byte a byte
  let rows = await loadAdsV2Shots(admin, order.id)
  if (!rows) return
  // Linhas que faltam (o /start caiu entre o débito e o insert): recria pelo plano gravado, sem duplicar.
  const planned = order.plan?.shots ?? []
  const have = new Set(rows.map((r) => r.idx))
  const missing = planned.filter((s) => !have.has(s.idx))
  // KINEO-ATOR-ANUNCIO-2026-10-09 — a linha do ator também é recriada (só em pedido novo: a refação copia a do pai, se pronta).
  const presenterPlan = order.parent_order_id ? null : adsV2PresenterPlanOf(order.plan)
  const presenterMissing = !!presenterPlan && !have.has(ADS_V2_PRESENTER_IDX)
  if (missing.length > 0 || presenterMissing) {
    const young = ageMs(order.started_at) < ADS_V2_ROWS_GRACE_MS
    if (order.parent_order_id) {
      // Refação: as linhas são CÓPIAS do pai + 1 plano refeito. Recriar pelo plano mandaria o anúncio INTEIRO à fal.
      if (!young) await failAdsV2Order(admin, order, 'retake_rows_missing', '/lib/ads/v2Advance')
      return
    }
    // KINEO-ADS-AMOSTRA-2026-10-09 — a amostra grátis não tem débito para conferir: a chave 'adssample-…' gravada pela
    // trava do /start (credits_charged 0) é a prova de que o início foi autorizado; recria as linhas como o pago.
    const debit = isAdsSampleRef(order.billing_ref) && order.credits_charged === 0
      ? ({ ok: true, refunded: false, amount: 0 } as const)
      : order.billing_ref
      ? await confirmAdsV2Debit(admin, { userId: order.user_id, billingRef: order.billing_ref, cost: order.credits_charged })
      : ({ ok: false, reason: 'missing' } as const)
    if (!debit.ok || debit.refunded) {
      if (!young) await failAdsV2Order(admin, order, 'rows_missing_debit_unconfirmed', '/lib/ads/v2Advance')
      return
    }
    await admin.from('ads_v2_shots').upsert(buildInitialShotRows(order.id, order.tier, { shots: missing, ...(presenterMissing && presenterPlan ? { presenter: presenterPlan } : {}) }), { onConflict: 'order_id,idx,attempt', ignoreDuplicates: true })
    rows = (await loadAdsV2Shots(admin, order.id)) ?? rows
  }
  // 1. Consulta/copia/marca cada plano em andamento (em lotes, para não estourar o prazo).
  const active = latestShots(rows).filter((r) => !READY.has(r.status) && r.status !== 'failed' && r.status !== 'stuck')
  for (let i = 0; i < active.length; i += ADS_V2_BATCH_SIZE) {
    await Promise.all(active.slice(i, i + ADS_V2_BATCH_SIZE).map((r) => pollOne(admin, order, r).catch((e) => console.warn('[ads-v2] poll falhou:', e instanceof Error ? e.message : String(e)))))
  }
